//! The portal embedded in the binary (ADR-0020, § 1): the static table
//! generated by `build.rs` from `portal/dist/`, and how its files are
//! served.
//!
//! - `GET /` serves `index.html`; any other path serves the file of that
//!   name, never a directory listing nor a fallback;
//! - the brotli variant is sent to a browser that accepts it
//!   (`Accept-Encoding: br`), with `Vary: Accept-Encoding`;
//! - the `ETag` is the SHA-256 of the variant sent; `If-None-Match` gives
//!   `304`;
//! - `Cache-Control`: `no-store` for `index.html`, `public, max-age=31536000,
//!   immutable` for the files named by their digest (`assets/`), `no-cache`
//!   for the others (revalidated by their `ETag`).
//!
//! Without a portal in the binary, every path answers `503` `WEB-E008`.

use http_body_util::Full;
use hyper::body::Bytes;
use hyper::header::{
    ACCEPT_ENCODING, CACHE_CONTROL, CONTENT_ENCODING, CONTENT_TYPE, ETAG, HeaderMap, HeaderValue,
    IF_NONE_MATCH, VARY,
};
use hyper::{Response, StatusCode};

/// One variant of a file: its bytes and its quoted `ETag`.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Variant {
    /// The bytes sent.
    pub bytes: &'static [u8],
    /// The `ETag`, quoted.
    pub etag: &'static str,
}

/// One file of the portal.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Asset {
    /// Its path under the root, without the leading `/`.
    pub path: &'static str,
    /// Its media type.
    pub content_type: &'static str,
    /// The SHA-256 of its bytes, lower-case hex, as in `SHA256SUMS`.
    pub sha256: &'static str,
    /// The file itself.
    pub raw: Variant,
    /// Its brotli variant, when smaller.
    pub brotli: Option<Variant>,
}

mod embedded {
    use super::Asset;
    include!(concat!(env!("OUT_DIR"), "/portal.rs"));
}

/// A set of portal files and their `SHA256SUMS`.
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct Portal {
    sums: Option<&'static str>,
    files: &'static [Asset],
}

impl std::fmt::Debug for Portal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Portal")
            .field("files", &self.files.len())
            .finish_non_exhaustive()
    }
}

/// The portal embedded in this binary (empty without `portal/dist/`).
pub static EMBEDDED: Portal = Portal {
    sums: embedded::SUMS,
    files: embedded::FILES,
};

/// What `ostena core portal-manifest` reports.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Manifest {
    /// SHA-256 of `SHA256SUMS`: the digest an evaluator compares with a
    /// rebuild of the portal from the sources.
    pub digest: String,
    /// `SHA256SUMS` itself.
    pub sums: &'static str,
    /// Number of files served (brotli variants not counted).
    pub files: usize,
}

/// Why the embedded portal cannot be vouched for.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ManifestError {
    /// Built without `portal/dist/`.
    #[error("aucun portail embarqué : binaire construit sans portal/dist (cargo xtask portal)")]
    Absent,
    /// A file differs from its digest, or `SHA256SUMS` lists another set.
    #[error("portail embarqué incohérent : {0}")]
    Mismatch(String),
}

fn hex(bytes: &[u8]) -> String {
    use std::fmt::Write as _;
    bytes.iter().fold(String::new(), |mut s, b| {
        let _ = write!(s, "{b:02x}");
        s
    })
}

impl Portal {
    /// A portal made of `files`, listed by `sums` (`None`: no portal).
    pub const fn new(sums: Option<&'static str>, files: &'static [Asset]) -> Self {
        Self { sums, files }
    }

    /// Whether the binary has a portal.
    pub fn is_present(&self) -> bool {
        self.sums.is_some() && !self.files.is_empty()
    }

    /// The file served at `path` (`/` is `index.html`).
    pub fn find(&self, path: &str) -> Option<&'static Asset> {
        let name = match path {
            "/" => "index.html",
            other => other.strip_prefix('/')?,
        };
        self.files.iter().find(|a| a.path == name)
    }

    /// Checks every embedded byte against `SHA256SUMS` (with
    /// `ostena-crypto`) and returns its digest.
    ///
    /// # Errors
    ///
    /// [`ManifestError`].
    pub fn manifest(&self) -> Result<Manifest, ManifestError> {
        let sums = self.sums.ok_or(ManifestError::Absent)?;
        if self.files.is_empty() {
            return Err(ManifestError::Absent);
        }
        let mut computed: Vec<(String, String)> = Vec::new();
        for asset in self.files {
            let raw = hex(&ostena_crypto::sha256::digest(asset.raw.bytes));
            if raw != asset.sha256 || asset.raw.etag != format!("\"{raw}\"") {
                return Err(ManifestError::Mismatch(format!(
                    "{} ne correspond pas à son empreinte",
                    asset.path
                )));
            }
            computed.push((asset.path.to_owned(), raw));
            if let Some(br) = asset.brotli {
                let digest = hex(&ostena_crypto::sha256::digest(br.bytes));
                if br.etag != format!("\"br-{digest}\"") {
                    return Err(ManifestError::Mismatch(format!(
                        "{}.br ne correspond pas à son empreinte",
                        asset.path
                    )));
                }
                computed.push((format!("{}.br", asset.path), digest));
            }
        }
        computed.sort();
        let expected = computed
            .iter()
            .fold(String::new(), |mut out, (path, digest)| {
                use std::fmt::Write as _;
                let _ = writeln!(out, "{digest}  {path}");
                out
            });
        if expected != sums {
            return Err(ManifestError::Mismatch(
                "SHA256SUMS ne décrit pas les fichiers embarqués".into(),
            ));
        }
        Ok(Manifest {
            digest: hex(&ostena_crypto::sha256::digest(sums.as_bytes())),
            sums,
            files: self.files.len(),
        })
    }
}

/// Whether `headers` accept brotli: a `br` coding whose weight is not zero.
fn accepts_brotli(headers: &HeaderMap) -> bool {
    headers
        .get_all(ACCEPT_ENCODING)
        .iter()
        .filter_map(|v| v.to_str().ok())
        .flat_map(|v| v.split(','))
        .any(|coding| {
            let mut parts = coding.split(';').map(str::trim);
            parts.next().is_some_and(|c| c.eq_ignore_ascii_case("br"))
                && !parts.any(|p| {
                    p.strip_prefix("q=")
                        .is_some_and(|q| q.parse::<f32>().is_ok_and(|q| q <= 0.0))
                })
        })
}

/// The response for `asset`, given the request headers.
pub fn serve(asset: &Asset, headers: &HeaderMap) -> Response<Full<Bytes>> {
    let variant = asset.brotli.filter(|_| accepts_brotli(headers));
    let sent = variant.unwrap_or(asset.raw);
    let not_modified = headers
        .get_all(IF_NONE_MATCH)
        .iter()
        .filter_map(|v| v.to_str().ok())
        .flat_map(|v| v.split(','))
        .any(|tag| {
            let tag = tag.trim();
            tag == sent.etag || tag.strip_prefix("W/") == Some(sent.etag)
        });
    let mut response = if not_modified {
        let mut r = Response::new(Full::new(Bytes::new()));
        *r.status_mut() = StatusCode::NOT_MODIFIED;
        r
    } else {
        Response::new(Full::new(Bytes::from_static(sent.bytes)))
    };
    let out = response.headers_mut();
    out.insert(CONTENT_TYPE, HeaderValue::from_static(asset.content_type));
    out.insert(ETAG, HeaderValue::from_static(sent.etag));
    if asset.brotli.is_some() {
        out.insert(VARY, HeaderValue::from_static("Accept-Encoding"));
    }
    if variant.is_some() {
        out.insert(CONTENT_ENCODING, HeaderValue::from_static("br"));
    }
    let cache = if asset.path == "index.html" {
        "no-store"
    } else if asset.path.starts_with("assets/") {
        "public, max-age=31536000, immutable"
    } else {
        "no-cache"
    };
    out.insert(CACHE_CONTROL, HeaderValue::from_static(cache));
    response
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn brotli_negotiation() {
        let mut h = HeaderMap::new();
        assert!(!accepts_brotli(&h));
        for (value, yes) in [
            ("gzip, deflate, br, zstd", true),
            ("br;q=0.5", true),
            ("BR", true),
            ("br;q=0", false),
            ("br; q=0.0", false),
            ("gzip", false),
            ("brotli", false),
        ] {
            h.insert(ACCEPT_ENCODING, HeaderValue::from_static(value));
            assert_eq!(accepts_brotli(&h), yes, "{value}");
        }
    }

    const HELLO: &str = "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824";

    static GOOD: [Asset; 1] = [Asset {
        path: "index.html",
        content_type: "text/html; charset=utf-8",
        sha256: HELLO,
        raw: Variant {
            bytes: b"hello",
            etag: "\"2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824\"",
        },
        brotli: None,
    }];
    static TAMPERED: [Asset; 1] = [Asset {
        raw: Variant {
            bytes: b"hellO",
            etag: GOOD[0].raw.etag,
        },
        ..GOOD[0]
    }];

    #[test]
    fn the_manifest_vouches_for_every_byte() {
        let sums = "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824  index.html\n";
        let m = Portal::new(Some(sums), &GOOD).manifest().unwrap();
        assert_eq!(
            m.digest,
            hex(&ostena_crypto::sha256::digest(sums.as_bytes()))
        );
        assert_eq!(m.files, 1);
        assert!(matches!(
            Portal::new(Some(sums), &TAMPERED).manifest(),
            Err(ManifestError::Mismatch(_))
        ));
        // SHA256SUMS listing another set of files.
        let other = format!("{sums}{HELLO}  extra.js\n");
        let other: &'static str = Box::leak(other.into_boxed_str());
        assert!(matches!(
            Portal::new(Some(other), &GOOD).manifest(),
            Err(ManifestError::Mismatch(_))
        ));
        assert_eq!(
            Portal::new(None, &GOOD).manifest(),
            Err(ManifestError::Absent)
        );
        assert_eq!(
            Portal::new(Some(sums), &[]).manifest(),
            Err(ManifestError::Absent)
        );
        let portal = Portal::new(Some(sums), &GOOD);
        assert!(portal.find("/").is_some() && portal.find("/index.html").is_some());
        assert!(portal.find("index.html").is_none() && portal.find("/x").is_none());
    }

    #[test]
    fn the_embedded_portal_matches_its_digests() {
        match EMBEDDED.manifest() {
            Ok(m) => {
                assert!(EMBEDDED.find("/").is_some());
                assert_eq!(m.digest.len(), 64);
            }
            Err(ManifestError::Absent) => assert!(!EMBEDDED.is_present()),
            Err(e) => panic!("{e}"),
        }
    }
}
